import assert from 'node:assert/strict';
import { execFileSync, spawnSync } from 'node:child_process';
import { copyFileSync, mkdirSync, mkdtempSync, readFileSync, rmSync, symlinkSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
const lane = '/home/genie/.local/share/mikro-engine-split/experiments-g8/final-local-smokes/history-only-reword-6qjyzwas/tree';
const parent = '/home/genie/.local/share/mikro-engine-split/experiments-g8/final-local-smokes';
const repo = mkdtempSync(join(parent, 'catalog-shared-actual-red-'));
const env = { PATH: process.env.PATH, HOME: repo, GENIE_HOME: join(repo, '.genie'), GIT_CONFIG_GLOBAL: '/dev/null',
  GIT_CONFIG_NOSYSTEM: '1', GIT_AUTHOR_DATE: '2026-01-01T00:00:00Z', GIT_COMMITTER_DATE: '2026-01-01T00:00:00Z' };
const git = (args: string[], input?: string) => execFileSync('git', args, { cwd: repo, env, input, encoding: 'utf8' }).trim();
const commitTree = (tree: string, parents: string[], message: string) => git(['commit-tree', tree,
  ...parents.flatMap((parent) => ['-p', parent])], `${message}\n`);
const importSource = (first: string, second: string) => {
  git(['read-tree', first]);
  git(['read-tree', '--prefix=mikro/', `${second}^{tree}`]);
  return commitTree(git(['write-tree']), [first, second],
    `feat(mikro): import source\n\ngit-subtree-dir: mikro\ngit-subtree-split: ${second}`);
};
try {
  mkdirSync(join(repo, 'scripts'));
  mkdirSync(join(repo, 'src/lib'), { recursive: true });
  mkdirSync(join(repo, 'skills/current'), { recursive: true });
  copyFileSync(join(lane, 'scripts/legacy-skills-catalog.ts'), join(repo, 'scripts/legacy-skills-catalog.ts'));
  copyFileSync(join(lane, 'scripts/git-history-ownership.ts'), join(repo, 'scripts/git-history-ownership.ts'));
  symlinkSync(join(lane, 'node_modules'), join(repo, 'node_modules'), 'dir');
  writeFileSync(join(repo, '.gitignore'), 'node_modules\n');
  writeFileSync(join(repo, 'skills/current/SKILL.md'), '---\nname: current\ndescription: Current Genie skill\n---\n');
  writeFileSync(join(repo, 'src/lib/legacy-skills-catalog.ts'),
    'export const LEGACY_SKILL_NAMES: readonly string[] = [];\nexport const LEGACY_SKILL_DESCRIPTIONS: readonly string[] = [];\n');
  git(['init', '-q', '-b', 'main']);
  git(['config', 'user.name', 'Catalog graph fixture']);
  git(['config', 'user.email', 'fixture@example.invalid']);
  git(['config', 'commit.gpgsign', 'false']);
  git(['config', 'core.hooksPath', '/dev/null']);
  git(['add', '.']);
  git(['commit', '-qm', 'chore: seed catalog']);
  const base = git(['rev-parse', 'HEAD']);
  const baseTree = git(['rev-parse', 'HEAD^{tree}']);
  mkdirSync(join(repo, 'skills/shared-retired'), { recursive: true });
  const description = 'Unique legitimate shared Genie retirement proof';
  writeFileSync(join(repo, 'skills/shared-retired/SKILL.md'),
    `---\nname: shared-retired\ndescription: ${description}\n---\n`);
  git(['add', '.']);
  git(['commit', '-qm', 'feat: deliver shared Genie skill']);
  const shared = git(['rev-parse', 'HEAD']);
  rmSync(join(repo, 'skills/shared-retired'), { recursive: true });
  git(['add', '.']);
  git(['commit', '-qm', 'chore: retire shared Genie skill']);
  const genie = git(['rev-parse', 'HEAD']);
  const foreignSeed = commitTree(baseTree, [], 'chore: seed unrelated source');
  const foreignSkill = git(['hash-object', '-w', '--stdin'], '---\nname: foreign-only\ndescription: Foreign Mikro only proof\n---\n');
  const foreignSkillTree = git(['mktree'], `100644 blob ${foreignSkill}\tSKILL.md\n`);
  const foreignSkillsTree = git(['mktree'], `040000 tree ${foreignSkillTree}\tforeign-only\n`);
  const foreignTree = git(['mktree'], `040000 tree ${foreignSkillsTree}\tskills\n`);
  const source = commitTree(foreignTree, [shared], 'update: foreign source');
  const nested = importSource(foreignSeed, source);
  const outer = importSource(genie, nested);
  git(['reset', '--hard', outer]);
  assert.equal(git(['merge-base', '--is-ancestor', shared, genie]), '');
  assert.equal(git(['rev-parse', `${nested}:mikro`]), git(['rev-parse', `${source}^{tree}`]));
  assert.equal(git(['rev-parse', `${outer}:mikro`]), git(['rev-parse', `${nested}^{tree}`]));
  const result = spawnSync(process.execPath, ['scripts/legacy-skills-catalog.ts'], { cwd: repo, env, encoding: 'utf8' });
  assert.equal(result.status, 0, result.stderr);
  assert.ok(!result.stdout.includes('Foreign Mikro only proof'), 'foreign source must remain outside catalog');
  const observed = { base, shared, genie, foreignSeed, source, nested, outer, catalogExit: result.status,
    generatedCatalog: result.stdout, legitimateGenieEntryPresent: result.stdout.includes(description),
    foreignEntryPresent: result.stdout.includes('Foreign Mikro only proof'), externalModelCalls: 0, jevCalls: 0 };
  console.log(JSON.stringify(observed));
  assert.ok(observed.legitimateGenieEntryPresent, 'shared Genie retirement proof must survive nested foreign import metadata');
} finally {
  rmSync(repo, { recursive: true, force: true });
}
